def _sb_conf():
    url = os.environ.get('SUPABASE_URL')
    key = os.environ.get('SUPABASE_KEY')
    try:
        url = url or st.secrets.get('SUPABASE_URL')
        key = key or st.secrets.get('SUPABASE_KEY')
    except Exception:
        pass
    if url and key:
        key = str(key).strip()
        privileged = key.startswith('sb_secret_')
        if key.startswith('eyJ'):
            try:
                payload = key.split('.')[1]
                claims = json.loads(base64.urlsafe_b64decode(payload + '=' * (-len(payload) % 4)))
                privileged = claims.get('role') == 'service_role'
            except (ValueError, IndexError, binascii.Error):
                privileged = False
        if not privileged:
            raise RuntimeError('SUPABASE_KEY: серверлік secret/service_role кілті қажет. Publishable/anon кілті қабылданбайды. Кілтті тек Streamlit Secrets ішінде сақтаңыз.')
        return (str(url).strip().rstrip('/'), key)
    return None

def _secret(name):
    v = os.environ.get(name)
    if not v:
        try:
            v = st.secrets.get(name)
        except Exception:
            v = None
    return str(v) if v else None

def _sb_call(conf, method, path, body=None, prefer=None, timeout=30):
    url, key = conf
    headers = {'apikey': key, 'Content-Type': 'application/json'}
    if key.startswith('eyJ'):
        headers['Authorization'] = 'Bearer ' + key
    if prefer:
        headers['Prefer'] = prefer
    data = json.dumps(body, ensure_ascii=False).encode('utf-8') if body is not None else None
    req = urllib.request.Request(url + '/rest/v1/' + path, data=data, headers=headers, method=method)
    try:
        with urllib.request.urlopen(req, timeout=timeout) as r:
            raw = r.read()
    except urllib.error.HTTPError as e:
        detail = ''
        try:
            detail = e.read().decode('utf-8', 'replace')[:200]
        except Exception:
            pass
        raise RuntimeError('HTTP %s %s' % (e.code, detail))
    return json.loads(raw.decode('utf-8')) if raw else None

def _sb_load_all(conf):
    out, off, step = ({}, 0, 200)
    while True:
        rows = _sb_call(conf, 'GET', '%s?select=key,value&key=not.like.ubt_server_exam_large_blob_*&order=key.asc&limit=%d&offset=%d' % (_TABLE, step, off))
        for r in rows or []:
            if isinstance(r, dict) and isinstance(r.get('key'), str) and isinstance(r.get('value'), str):
                out[r['key']] = r['value']
        if not rows or len(rows) < step:
            return out
        off += step

def _sb_upsert(conf, items):
    batch, size = ([], 0)
    for k, v in items:
        if batch and size + len(v) > 3000000:
            _sb_call(conf, 'POST', '%s?on_conflict=key' % _TABLE, batch, prefer='resolution=merge-duplicates,return=minimal')
            batch, size = ([], 0)
        batch.append({'key': k, 'value': v})
        size += len(v)
    if batch:
        _sb_call(conf, 'POST', '%s?on_conflict=key' % _TABLE, batch, prefer='resolution=merge-duplicates,return=minimal')

def _sb_delete(conf, key):
    _sb_call(conf, 'DELETE', '%s?key=eq.%s' % (_TABLE, urllib.parse.quote(key, safe='')), prefer='return=minimal')

def _book_storage(conf, method, path, data=None, content_type='application/json'):
    base, key = conf
    headers = {'apikey': key, 'Content-Type': content_type}
    if key.startswith('eyJ'):
        headers['Authorization'] = 'Bearer ' + key
    req = urllib.request.Request(base + '/storage/v1/' + path, data=data, headers=headers, method=method)
    with urllib.request.urlopen(req, timeout=50) as response:
        raw = response.read()
    return json.loads(raw) if raw else {}

def _book_storage_bucket(conf):
    try:
        bucket = _book_storage(conf, 'GET', 'bucket/' + _BOOK_BUCKET)
        if bucket.get('public') is True:
            raise ValueError('Кітаптар қоймасы жабық болуы тиіс')
        current_limit = bucket.get('file_size_limit') or bucket.get('fileSizeLimit') or 0
        if int(current_limit or 0) < _MAX_BOOK_BYTES:
            _book_storage(conf, 'PUT', 'bucket/' + _BOOK_BUCKET, _jdump({'public': False, 'file_size_limit': _MAX_BOOK_BYTES, 'allowed_mime_types': ['application/pdf']}).encode('utf-8'))
    except urllib.error.HTTPError as exc:
        if exc.code != 404:
            raise
        _book_storage(conf, 'POST', 'bucket', _jdump({'id': _BOOK_BUCKET, 'name': _BOOK_BUCKET, 'public': False, 'file_size_limit': _MAX_BOOK_BYTES, 'allowed_mime_types': ['application/pdf']}).encode('utf-8'))

def _hash_pw(pw, salt=None, it=_PBKDF_ITER):
    salt = salt or secrets.token_hex(16)
    dk = hashlib.pbkdf2_hmac('sha256', pw.encode('utf-8'), bytes.fromhex(salt), it)
    return {'alg': 'pbkdf2_sha256', 'it': it, 'salt': salt, 'hash': dk.hex()}

def _check_pw(pw, ph):
    try:
        dk = hashlib.pbkdf2_hmac('sha256', pw.encode('utf-8'), bytes.fromhex(ph['salt']), int(ph['it']))
        return hmac.compare_digest(dk.hex(), str(ph['hash']))
    except Exception:
        return False

def _jload(raw, typ, default):
    try:
        v = json.loads(raw)
    except Exception:
        return default
    return v if isinstance(v, typ) else default

def _jdump(v):
    return json.dumps(v, ensure_ascii=False)

@st.cache_resource
@st.cache_resource
def _store():
    data = {}
    try:
        with open(DATA_FILE, 'r', encoding='utf-8') as f:
            raw = json.load(f)
        for k, v in raw.items():
            data[k] = v['v'] if isinstance(v, dict) and 'v' in v else v
    except Exception:
        data = {}
    state = {'db': data, 'sb': _sb_conf(), 'ok': False, 'err': '', 'dirty': set(), 'deleted': set(), 'lock': threading.RLock(), 'flush_lock': threading.Lock(), 'retry_t': 0.0, 'flushing': False, 'flush_again': False, 'syncing': False, 'sessions': {}, 'chat_claims': {}, 'fails': {}, 'reg': {}, 'exams': {}, 'rev': 1}
    _remote_sync(state)
    for _key, _raw in list(state['db'].items()):
        _clean = _purge_filter_raw(state, _key, _raw)
        if _clean != _raw:
            _put(state, _key, _clean)
    _restore_exams(state)
    _seed_real_bank_demo(state)
    _migrate_start(state)
    return state

# Permanent question removal. The guard stores hashes only, never question content.
_PURGE_POLICY = 'ubt_server_exam_purge_policy'
_PURGE_REMOVE = object()

def _purge_digest(value):
    return hashlib.sha256(' '.join(str(value or '').split()).casefold().encode('utf-8')).hexdigest()

def _purge_policy(state):
    raw = state['db'].get(_PURGE_POLICY, '{}')
    cached = state.get('purge_policy_cache')
    if cached and cached[0] == raw:
        return cached[1]
    policy = _jload(raw, dict, {})
    policy['_texts'] = set(policy.get('texts', []))
    policy['_ids'] = set(policy.get('ids', []))
    state['purge_policy_cache'] = (raw, policy)
    return policy

def _purge_scrub(value, policy):
    texts, ids = (policy.get('_texts', set()), policy.get('_ids', set()))
    if not texts and (not ids):
        return value
    if isinstance(value, str):
        if _purge_digest(value) in texts or _purge_digest(value) in ids:
            return _PURGE_REMOVE
        if value[:1] in ('[', '{'):
            try:
                decoded = json.loads(value)
            except (ValueError, TypeError):
                return value
            cleaned = _purge_scrub(decoded, policy)
            if cleaned is _PURGE_REMOVE:
                return _PURGE_REMOVE
            if cleaned != decoded:
                return _jdump(cleaned)
        if '|' in value and _purge_digest(value.split('|', 1)[-1]) in texts:
            return _PURGE_REMOVE
        return value
    if isinstance(value, list):
        if len(value) == 3 and all((isinstance(x, str) for x in value)) and (_purge_digest(value[-1]) in texts):
            return _PURGE_REMOVE
        out = []
        for item in value:
            cleaned = _purge_scrub(item, policy)
            if cleaned is not _PURGE_REMOVE:
                out.append(cleaned)
        return out
    if isinstance(value, dict):
        if any((isinstance(value.get(field), str) and _purge_digest(value[field]) in texts for field in ('text', 'question', 'front', 'questionText'))):
            return _PURGE_REMOVE
        if isinstance(value.get('id'), str) and _purge_digest(value['id']) in ids:
            return _PURGE_REMOVE
        out = {}
        for key, item in value.items():
            if _purge_digest(key) in ids or _purge_digest(key) in texts:
                continue
            cleaned = _purge_scrub(item, policy)
            if cleaned is not _PURGE_REMOVE:
                out[key] = cleaned
        if isinstance(value.get('questions'), list) and out.get('questions') != value['questions']:
            if not out.get('questions'):
                return _PURGE_REMOVE
            for key in ('answers', 'review', 'checked', 'flags', 'correctAnswers', 'questionOrder'):
                out.pop(key, None)
        return out
    return value

def _purge_filter_raw(state, key, raw):
    if key in (_PURGE_POLICY, 'ubt_purge_generation'):
        return raw
    policy = _purge_policy(state)
    if not policy.get('_texts') and (not policy.get('_ids')):
        return raw
    try:
        value = json.loads(raw)
    except (ValueError, TypeError):
        return raw
    clean = _purge_scrub(value, policy)
    if clean is _PURGE_REMOVE:
        return '{}' if isinstance(value, dict) else '[]'
    return raw if clean == value else _jdump(clean)

def _purge_builtins(state):
    policy = _purge_policy(state)
    if policy.get('disableBuiltins'):
        return []
    clean = _purge_scrub(globals().get('_BUILTIN_BANK_TESTS', []), policy)
    return clean if isinstance(clean, list) else []

def _purge_inventory(state):
    groups = {}

    def visit(value, subject='', source=''):
        if isinstance(value, dict):
            subject = str(value.get('subject') or subject or 'other')
            source = str(value.get('source') or value.get('origin') or value.get('topic') or source or 'База')
            text = value.get('text', value.get('question'))
            if isinstance(text, str) and isinstance(value.get('options'), list):
                token = _purge_digest(text)
                row = groups.setdefault(token, {'id': 'purge:' + token, 'text': text, 'subject': subject, 'source': source})
                if value.get('id'):
                    row.setdefault('_ids', set()).add(str(value['id']))
            for item in value.values():
                if isinstance(item, (list, dict)):
                    visit(item, subject, source)
        elif isinstance(value, list):
            for item in value:
                visit(item, subject, source)
        elif isinstance(value, str) and value[:1] in ('[', '{'):
            try:
                visit(json.loads(value), subject, source)
            except (ValueError, TypeError):
                pass
    for key, raw in state['db'].items():
        if key == _PURGE_POLICY:
            continue
        try:
            value = json.loads(raw)
        except (ValueError, TypeError):
            continue
        visit(value)
    visit(_purge_builtins(state), '', 'Дайын тесттер')
    return groups

def _purge_request(state, sess, data):
    if not sess or not sess.get('admin') or sess.get('uid') != 'admin' or sess.get('codeGuest') or sess.get('juniorAdmin'):
        return {'ok': False, 'msg': 'Тек басты админге қолжетімді'}
    action = data.get('action')
    if action == 'list':
        with state['lock']:
            rows = list(_purge_inventory(state).values())
            subject, query = (str(data.get('subject') or ''), str(data.get('query') or '').casefold())
            filtered = [r for r in rows if (not subject or r['subject'] == subject) and (not query or query in r['text'].casefold() or query in r['source'].casefold())]
            offset = data.get('offset', 0)
            if type(offset) is not int or offset < 0:
                offset = 0
            counts = {}
            for row in rows:
                counts[row['subject']] = counts.get(row['subject'], 0) + 1
            return {'ok': True, 'items': [{k: v for k, v in r.items() if k != '_ids'} for r in filtered[offset:offset + 50]], 'total': len(filtered), 'allTotal': len(rows), 'counts': counts, 'generation': _purge_policy(state).get('generation', '')}
    if action not in ('selected', 'all') or data.get('confirm') != 'DELETE':
        return {'ok': False, 'msg': 'Жоюды растаңыз'}
    conf = state.get('sb')
    if not conf:
        return {'ok': False, 'msg': 'Сервер бапталмаған. SUPABASE_URL және серверлік SUPABASE_KEY қажет.'}
    with state['flush_lock']:
        with state['lock']:
            try:
                remote = _sb_load_all(conf)
            except Exception:
                return {'ok': False, 'msg': 'Серверге қосылу мүмкін болмады. Ештеңе жойылған жоқ.'}
            for key, raw in remote.items():
                if key not in state['dirty'] and key not in state['deleted']:
                    state['db'][key] = raw
            inventory = _purge_inventory(state)
            targets = set(inventory) | _lg_all_text_hashes(state) if action == 'all' else set()
            if action == 'selected':
                wanted = data.get('ids')
                if not isinstance(wanted, list) or not 1 <= len(wanted) <= 20000 or any((not isinstance(x, str) for x in wanted)):
                    return {'ok': False, 'msg': 'Сұрақтарды таңдаңыз'}
                wanted = set(wanted)
                inventory.update(_lg_selected_inventory(state, wanted))
                for token, row in inventory.items():
                    local = 'local:' + json.dumps(['', row['subject'], row['text'].strip().lower()], ensure_ascii=False, separators=(',', ':'))
                    if row['id'] in wanted or row.get('_ids', set()) & wanted or local in wanted:
                        targets.add(token)
                for q in _jload(state['db'].get('ubt_question_catalog', '[]'), list, []):
                    if not isinstance(q, dict):
                        continue
                    local = 'local:' + json.dumps([q.get('authorId') or '', q.get('subject') or 'other', str(q.get('text') or '').strip().lower()], ensure_ascii=False, separators=(',', ':'))
                    if q.get('id') in wanted or local in wanted:
                        targets.add(_purge_digest(q.get('text')))
                if not targets:
                    return {'ok': False, 'msg': 'Сұрақ табылмады. Тізімді жаңартыңыз.'}
            previous = _purge_policy(state)
            text_hashes = set(previous.get('texts', [])) | targets
            id_hashes = set(previous.get('ids', []))
            for token in targets:
                for ident in inventory.get(token, {}).get('_ids', set()):
                    id_hashes.add(_purge_digest(ident))
            policy = {'texts': sorted(text_hashes), 'ids': sorted(id_hashes), 'generation': secrets.token_hex(16), 'disableBuiltins': bool(action == 'all' or previous.get('disableBuiltins'))}
            _put(state, _PURGE_POLICY, _jdump(policy))
            _put(state, 'ubt_purge_generation', _jdump(policy['generation']))
            parsed = _purge_policy(state)
            try:
                _lg_purge_data(state, parsed, action == 'all')
            except Exception:
                return {'ok': False, 'msg': 'Үлкен база толық тазаланбады. Жоюды қайта орындаңыз.', 'pending': True}
            for key, raw in list(state['db'].items()):
                if key in (_PURGE_POLICY, 'ubt_purge_generation'):
                    continue
                clean = _purge_filter_raw(state, key, raw)
                if clean != raw:
                    if key.startswith('ubt_server_exam_') and key != 'ubt_server_exam_real_bank':
                        _drop(state, key)
                    else:
                        _put(state, key, clean)
            for token, exam in list(state.get('exams', {}).items()):
                clean = _purge_scrub(exam, parsed)
                if clean is _PURGE_REMOVE or clean != exam:
                    state['exams'].pop(token, None)
                    _drop(state, 'ubt_server_exam_' + token)
            if action == 'all':
                for key in list(state['db']):
                    if key.startswith(('ubt_qbank_', 'ubt_ubt140_selection_', 'ubt_subject_selection_')) or key in ('ubt_question_catalog_deleted', 'ubt_question_catalog_files', 'ubt_hidden_source_tests'):
                        _drop(state, key)
                _put(state, 'ubt_tests', '[]')
                _put(state, 'ubt_question_catalog', '[]')
                _put(state, 'ubt_server_exam_real_bank', '{}')
                _put(state, 'ubt_server_exam_real_demo_v1', 'true')
            for key in list(state):
                if 'cache' in key or key in ('approved_shared_ids', 'subject_migration_source'):
                    state.pop(key, None)
            state['rev'] = state.get('rev', 1) + 1
            changed = [(k, state['db'][k]) for k in state['dirty'] if k in state['db']]
            removed = list(state['deleted'])
            try:
                _sb_upsert(conf, [(_PURGE_POLICY, state['db'][_PURGE_POLICY])])
                _sb_upsert(conf, changed)
                for key in removed:
                    _sb_delete(conf, key)
                actual = _sb_load_all(conf)
                if any((actual.get(k) != v for k, v in changed)) or any((k in actual for k in removed)):
                    raise RuntimeError('Deletion verification failed')
                if any((_purge_filter_raw(state, k, v) != v for k, v in actual.items() if k != _PURGE_POLICY)):
                    raise RuntimeError('Question copy still exists')
                _db_save(state['db'])
            except Exception:
                state['err'] = 'Тұрақты жою толық расталмады'
                return {'ok': False, 'msg': 'Жою толық аяқталғаны расталмады. Байланысты тексеріп, «Барлығын жою» әрекетін қайта орындаңыз.', 'pending': True}
            for key, raw in changed:
                if state['db'].get(key) == raw:
                    state['dirty'].discard(key)
            state['deleted'].difference_update(removed)
            state['ok'], state['err'] = (True, '')
            return {'ok': True, 'count': len(targets), 'verified': True, 'generation': policy['generation']}



def _put(state, k, v):
    v = _purge_filter_raw(state, k, v)
    if k in state['db'] and state['db'][k] == v and (k not in state['deleted']):
        return
    state['db'][k] = v
    state['rev'] = state.get('rev', 1) + 1
    state['dirty'].add(k)
    state['deleted'].discard(k)

def _drop(state, k):
    state['db'].pop(k, None)
    state['rev'] = state.get('rev', 1) + 1
    state['dirty'].discard(k)
    state['deleted'].add(k)

def _commit(state):
    try:
        _db_save(state['db'])
    except Exception:
        pass
    _flush_async(state)

def _remote_sync(state):
    with state['flush_lock']:
        return _remote_sync_locked(state)

def _remote_sync_locked(state):
    """Supabase-тен барлық деректі алады (ол басым). Тек жергілікті бар кілттерді Supabase-ке жібереді."""
    conf = state.get('sb')
    state['retry_t'] = time.time()
    if not conf:
        return
    try:
        remote = _sb_load_all(conf)
    except Exception as e:
        state['err'] = repr(e)[:200]
        return
    with state['lock']:
        db = state['db']
        updated = False
        for k, v in remote.items():
            if k not in state['dirty'] and k not in state['deleted']:
                if db.get(k) != v:
                    db[k] = _purge_filter_raw(state, k, v)
                    if db[k] != v:
                        state['dirty'].add(k)
                    updated = True
        for k in list(db.keys()):
            if k not in remote:
                state['dirty'].add(k)
        if updated:
            state['rev'] += 1
        state['ok'] = True
        state['err'] = ''
    _restore_exams(state)
    _flush_async(state)
    _migrate_start(state)

def _flush(state):
    conf = state.get('sb')
    if not conf:
        return
    with state['flush_lock']:
        with state['lock']:
            items = [(k, state['db'][k]) for k in list(state['dirty']) if k in state['db']]
            for k in list(state['dirty']):
                if k not in state['db']:
                    state['dirty'].discard(k)
            dels = list(state['deleted'])
        if items:
            try:
                _sb_upsert(conf, items)
            except Exception as e:
                state['err'] = repr(e)[:200]
                return
            with state['lock']:
                for k, v in items:
                    if state['db'].get(k) == v:
                        state['dirty'].discard(k)
                state['err'] = ''
        for k in dels:
            try:
                _sb_delete(conf, k)
            except Exception as e:
                state['err'] = repr(e)[:200]
                break
            with state['lock']:
                state['deleted'].discard(k)

def _flush_async(state):
    if not state.get('sb'):
        return
    with state['lock']:
        if state['flushing']:
            state['flush_again'] = True
            return
        state['flushing'] = True

    def run():
        while True:
            try:
                _flush(state)
            except Exception as exc:
                state['err'] = repr(exc)[:200]
            with state['lock']:
                if not state['flush_again']:
                    state['flushing'] = False
                    return
                state['flush_again'] = False
    threading.Thread(target=run, daemon=True).start()

def _ensure_remote(state):
    """Байланыс үзілсе қайта қосады, жіберілмей қалған өзгерістерді қайта жібереді."""
    if not state.get('sb'):
        return
    if not state['ok']:
        with state['lock']:
            retry = not state['syncing'] and time.time() - state['retry_t'] > 20
            if retry:
                state['syncing'] = True
                state['retry_t'] = time.time()
        if retry:

            def reconnect():
                try:
                    _remote_sync(state)
                finally:
                    with state['lock']:
                        state['syncing'] = False
            threading.Thread(target=reconnect, daemon=True).start()
    elif state['dirty'] or state['deleted']:
        _flush_async(state)

def _store_mode(state):
    if not state.get('sb'):
        return 'local'
    return 'remote' if state['ok'] and (not state['dirty']) else 'pending' if state['ok'] else 'error'

def _db_save(db):
    tmp = DATA_FILE + '.tmp'
    with open(tmp, 'w', encoding='utf-8') as f:
        json.dump(db, f, ensure_ascii=False)
        f.flush()
        os.fsync(f.fileno())
    os.replace(tmp, DATA_FILE)

def _migrate_once(state):
    """Ашық мәтінді парольдерді хэшке айналдырады. Ескі ubt_admin_pass кілтін өшіреді."""
    with state['lock']:
        raw = state['db'].get('ubt_profiles')
        profs = _jload(raw, dict, None) if isinstance(raw, str) else None
        todo = []
        if profs:
            for k, p in profs.items():
                if isinstance(p, dict) and 'password' in p:
                    todo.append((k, p.get('password')))
    hashes = {}
    for k, pw in todo:
        if isinstance(pw, str) and pw:
            hashes[k] = (pw, _hash_pw(pw))
    changed = False
    with state['lock']:
        raw = state['db'].get('ubt_profiles')
        profs = _jload(raw, dict, None) if isinstance(raw, str) else None
        if profs:
            for k, p in profs.items():
                if isinstance(p, dict) and 'password' in p:
                    old = p.pop('password')
                    h = hashes.get(k)
                    if h and h[0] == old and (not p.get('ph')):
                        p['ph'] = h[1]
                    changed = True
            if changed:
                _put(state, 'ubt_profiles', _jdump(profs))
        ap = state['db'].get('ubt_admin_pass')
        if ap is not None:
            val = _jload(ap, str, '')
            if val and len(val) >= 4 and (val != 'admin123') and (not state['db'].get('ubt_admin_ph')):
                _put(state, 'ubt_admin_ph', _jdump(_hash_pw(val)))
            _drop(state, 'ubt_admin_pass')
            changed = True
        if changed:
            _commit(state)
    return changed

def _migrate_start(state):
    if state.get('migrating'):
        return
    state['migrating'] = True

    def run():
        try:
            _migrate_once(state)
        except Exception as e:
            print('[ubt-sec] migration error:', repr(e)[:200])
        finally:
            state['migrating'] = False
    threading.Thread(target=run, daemon=True).start()

def _profiles(state):
    rows = _jload(state['db'].get('ubt_profiles', '{}'), dict, {})
    return {k: dict(p, role='student') for k, p in rows.items() if isinstance(p, dict)}

def _pub_user(p):
    public = {k: v for k, v in p.items() if k not in ('ph', 'password', 'teacherApproved', 'teacherInfo', 'teacherSubject')}
    public['role'] = 'student'
    return public

_PROFILE_COMBINATIONS = [
 ('math','physics'),('math','informatics'),('math','geography'),('biology','chemistry'),('biology','geography'),
 ('english','worldhistory'),('german','worldhistory'),('french','worldhistory'),
 ('geography','english'),('geography','german'),('geography','french'),('worldhistory','law'),('worldhistory','geography'),
 ('kazakh','kazakh_literature'),('russian','russian_literature'),('chemistry','physics'),('creative','creative')]

def _profile_pair(state, uid):
    raw = state['db'].get('ubt_server_access_profile_pairs', '{}')
    cached = state.get('profile_pair_cache')
    if not cached or cached[0] is not raw:
        cached = (raw, _jload(raw, dict, {}))
        state['profile_pair_cache'] = cached
    return cached[1].get(uid, [])

def _person_profile(state, uid):
    raw = state['db'].get('ubt_profiles', '{}')
    cached = state.get('person_profile_cache')
    if not cached or cached[0] is not raw:
        cached = (raw, {p.get('id'): p for p in _profiles(state).values() if isinstance(p, dict)})
        state['person_profile_cache'] = cached
    return cached[1].get(uid, {})

def _set_profile_pair(state, uid, pair):
    if not isinstance(pair, list) or tuple(pair) not in _PROFILE_COMBINATIONS:
        return False
    pairs = _jload(state['db'].get('ubt_server_access_profile_pairs', '{}'), dict, {})
    pairs[uid] = pair
    _put(state, 'ubt_server_access_profile_pairs', _jdump(pairs))
    return True

def _allowed_subjects(state, sess):
    if not sess:
        return set()
    if sess.get('admin') or sess.get('juniorAdmin'):
        return set(_SUBJECT_NAMES)
    pair = _profile_pair(state, sess['uid'])
    if len(pair) != 2:
        return set()
    if pair == ['creative', 'creative']:
        return {'history', 'reading'}
    return set(pair) | {'history', 'mathlit', 'reading'}

def _subject_guard(state, sess, subject, questions=None):
    allowed = _allowed_subjects(state, sess)
    if not allowed:
        return 'Алдымен бейіндік пән жұбын таңдаңыз'
    required = {str(q.get('subject') or subject or '') for q in questions or []}
    if not required:
        required = {str(subject or '')}
    if not required or '' in required or (not required.issubset(allowed)):
        return 'Бұл тест сіз таңдаған пәндерге жатпайды'
    return ''

def _public_question(q, index):
    out = {k: q[k] for k in ('text', 'options', 'points', 'img', 'tbl', 'subject', 'subjectName', 'difficulty') if k in q}
    out['id'] = 'examq' + str(index)
    return out

def _review_fingerprint(questions):

    def norm(value):
        return ' '.join(str(value).split()).casefold()
    data = sorted(((q.get('subject') or '', norm(q['text']), tuple(sorted((norm(x) for x in q['options'])))) for q in questions))
    return 'content:' + hashlib.sha256(_jdump(data).encode()).hexdigest()

def _review_record(state, sess, exam, answers):
    uid = sess['uid']
    own = bool(exam.get('selfAuthored'))
    signature = exam.get('reviewFamily') or exam['testId']
    family = hashlib.sha256((uid + '|' + ('own:' if own else 'shared:') + signature).encode()).hexdigest()
    usage = _jload(state['db'].get('ubt_server_exam_review_usage_' + sess['uid'], '{}'), dict, {})
    u = usage.setdefault(family, {'attempts': 0, 'opens': 0})
    u['attempts'] += 1
    eligible = (own or u['attempts'] == 1) and (not exam.get('noReview'))
    ident = 'review_' + secrets.token_hex(18)
    records = _jload(state['db'].get('ubt_server_exam_review_records_' + sess['uid'], '{}'), dict, {})
    records[ident] = {'uid': uid, 'family': family, 'own': own, 'eligible': eligible, 'questions': exam['questions'], 'answers': answers, 'topic': exam['topic'], 'created': time.time(), 'expires': time.time() + 30 * 86400}
    mine = sorted(((r['created'], k) for k, r in records.items() if r.get('uid') == uid))
    for _, key in mine[:-100]:
        records.pop(key, None)
    history = _jload(state['db'].get('ubt_hist_' + uid, '[]'), list, [])
    for row in history:
        old = records.get(row.get('reviewId'))
        if old and old['family'] == family:
            row['reviewAvailable'] = bool(old['eligible'] and u['opens'] < (5 if old['own'] else 1) and (old['own'] or u['attempts'] == 1))
    _put(state, 'ubt_hist_' + uid, _jdump(history))
    _put(state, 'ubt_server_exam_review_usage_' + sess['uid'], _jdump(usage))
    _put(state, 'ubt_server_exam_review_records_' + sess['uid'], _jdump(records))
    return (ident, bool(eligible and u['opens'] < (5 if own else 1)))

def _review_request(state, sess, typ, d):
    if not sess:
        return {'ok': False, 'msg': 'Аккаунтыңызға кіріңіз'}
    with state['lock']:
        records = _jload(state['db'].get('ubt_server_exam_review_records_' + sess['uid'], '{}'), dict, {})
        rec = records.get(str(d.get('reviewId') or ''))
        if not rec or rec.get('uid') != sess['uid'] or rec['expires'] < time.time():
            return {'ok': False, 'msg': 'Бұл нәтиженің жауаптары қолжетімсіз немесе мерзімі өткен'}
        issue = _subject_guard(state, sess, None, rec['questions'])
        if issue and typ != 'review_close':
            return {'ok': False, 'msg': issue}
        if typ == 'review_close':
            if rec.get('lease') == d.get('lease'):
                rec['active'] = False
            _put(state, 'ubt_server_exam_review_records_' + sess['uid'], _jdump(records))
            _commit(state)
            return {'ok': True}
        usage = _jload(state['db'].get('ubt_server_exam_review_usage_' + sess['uid'], '{}'), dict, {})
        u = usage.get(rec['family'], {'attempts': 0, 'opens': 0})
        limit = 5 if rec['own'] else 1
        if not rec['eligible'] or (not rec['own'] and u['attempts'] != 1) or u['opens'] >= limit:
            return {'ok': False, 'msg': 'Қатемен жұмысты қарау лимиті аяқталған. Қайта тапсырғанда ортақ тест жауаптары ашылмайды.'}
        if any((e.get('uid') == sess['uid'] and (not e.get('completed')) and (e.get('expires', 0) > time.time()) for e in state.get('exams', {}).values())):
            return {'ok': False, 'msg': 'Алдымен белсенді тестті аяқтаңыз'}
        u['opens'] += 1
        usage[rec['family']] = u
        for old in records.values():
            if old.get('uid') == sess['uid']:
                old['active'] = False
        rec.update(active=True, lease=secrets.token_urlsafe(24), leaseExpires=time.time() + 900)
        history = _jload(state['db'].get('ubt_hist_' + sess['uid'], '[]'), list, [])
        for row in history:
            item = records.get(row.get('reviewId'))
            if item and item['family'] == rec['family']:
                row['reviewAvailable'] = bool(item['eligible'] and u['opens'] < limit and (item['own'] or u['attempts'] == 1))
        _put(state, 'ubt_hist_' + sess['uid'], _jdump(history))
        _put(state, 'ubt_server_exam_review_usage_' + sess['uid'], _jdump(usage))
        _put(state, 'ubt_server_exam_review_records_' + sess['uid'], _jdump(records))
        _commit(state)
        return {'ok': True, 'reviewId': d['reviewId'], 'lease': rec['lease'], 'expires': rec['leaseExpires'], 'topic': rec['topic'], 'questions': [{**q, 'id': 'examq' + str(i)} for i, q in enumerate(rec['questions'])], 'answers': rec['answers'], 'remaining': limit - u['opens']}

def _start_personal_practice(state, sess, d):
    if not sess or sess.get('codeGuest'):
        return {'ok': False, 'msg': 'Аккаунтыңызға кіріңіз'}
    if not _can_upload_tests(state, sess):
        return {'ok': False, 'msg': 'Тест қосу үшін басты админнің рұқсаты қажет'}
    qs = d.get('questions')
    topic = str(d.get('topic') or 'Өз тестім')[:150]
    if not isinstance(qs, list) or not 1 <= len(qs) <= 500:
        return {'ok': False, 'msg': 'Тестте 1–500 сұрақ болуы керек'}
    if any((not isinstance(q, dict) or q.get('realBank') or (q.get('authorId') not in (None, '', sess['uid']) and (not (sess.get('admin') or sess.get('juniorAdmin')))) for q in qs)):
        return {'ok': False, 'msg': 'Ортақ тестті тек өзінің Бастау батырмасымен тапсырыңыз'}
    clean = []
    try:
        for q in qs:
            subject = q.get('subject')
            issue = _subject_guard(state, sess, subject)
            if issue:
                return {'ok': False, 'msg': issue}
            row = _school_test_payload([{'subject': subject, 'questions': [q]}])[0]['questions'][0]
            row.update(subject=subject, subjectName=_SUBJECT_NAMES[subject])
            clean.append(row)
        minutes = int(d.get('minutes', 30))
    except (ValueError, TypeError, OverflowError) as error:
        return {'ok': False, 'msg': str(error)}
    if not 1 <= minutes <= 300:
        return {'ok': False, 'msg': 'Уақыт 1–300 минут болсын'}
    family = _review_fingerprint(clean)
    with state['lock']:
        if not _exam_capacity(state, sess['uid']):
            return {'ok': False, 'msg': 'Алдымен белсенді тестті аяқтаңыз'}
        token = secrets.token_urlsafe(32)
        state['exams'][token] = {'uid': sess['uid'], 'testId': 'own_' + family.split(':', 1)[-1], 'assignmentId': None, 'classId': None, 'owner': True, 'reward': False, 'publishedQuota': False, 'questions': clean, 'topic': topic, 'is140': bool(d.get('is140')), 'selfAuthored': True, 'reviewFamily': family, 'expires': time.time() + minutes * 60 + 90}
        issue = _subscription_prepare(state, sess, state['exams'][token])
        if issue:
            state['exams'].pop(token, None)
            return {'ok': False, 'msg': issue, 'upgradeRequired': True}
        _save_exam(state, token)
    return {'ok': True, 'exam': token, 'questions': [_exam_question_meta(q, i) for i, q in enumerate(clean)], 'topic': topic, 'timer': minutes * 60, 'allowInstantFeedback': False}

def _profile_request(state, sess, typ, d):
    if not sess or sess.get('codeGuest'):
        return {'ok': False, 'msg': 'Аккаунтыңызға кіріңіз'}
    uid = sess['uid'] if typ == 'choose_profile_pair' else str(d.get('uid') or '')
    with state['lock']:
        profile = _person_profile(state, uid)
        if uid == 'admin' or uid in _admin_uids(state):
            return {'ok': False, 'msg': 'Пән жұбы тек оқушыға қажет'}
        if typ == 'owner_set_pair' and (not sess.get('admin')):
            return {'ok': False, 'msg': 'Тек басты админ өзгерте алады'}
        if typ == 'choose_profile_pair' and _profile_pair(state, uid):
            return {'ok': False, 'msg': 'Пәндерді өзгерту үшін басты админге хабарласыңыз'}
        if not _set_profile_pair(state, uid, d.get('pair')):
            return {'ok': False, 'msg': 'Тізімнен пән жұбын таңдаңыз'}
        _commit(state)
        return {'ok': True, 'pair': d['pair']}

def _secure_snapshot(state, sess, db):
    if sess['uid'] != 'admin':
        allowed = _allowed_subjects(state, sess)
        tests = _jload(db.get('ubt_tests', '[]'), list, [])
        db['ubt_tests'] = _jdump([t for t in tests if t.get('subject') in allowed and (not t.get('shopExclusive'))])
        catalog = _jload(db.get('ubt_question_catalog', '[]'), list, [])
        db['ubt_question_catalog'] = _jdump([q for q in catalog if q.get('authorId') == sess['uid'] and q.get('subject') in allowed])
        named = _jload(db.get('ubt_real_bank_tests', '[]'), list, [])
        db['ubt_real_bank_tests'] = _jdump([t for t in named if t.get('subject') in allowed])
        meta = _jload(db.get('ubt_real_bank_meta', '{}'), dict, {})
        db['ubt_real_bank_meta'] = _jdump({k: v for k, v in meta.items() if k in allowed})
        for key in list(db):
            if key.startswith('ubt_hist_'):
                rows = _jload(db[key], list, [])
                db[key] = _jdump([{k: v for k, v in r.items() if k not in ('questions', 'answers')} for r in rows if isinstance(r, dict)])
            elif key.startswith('ubt_mistakes_'):
                db[key] = '[]'
    info = _subscription_info(state, sess)
    db['ubt_entitlement'] = _jdump(info)
    if info['plan'] == 'free':
        for prefix in ('ubt_hist_', 'ubt_prog_'):
            key = prefix + sess['uid']
            if key in db:
                rows = _jload(db[key], list, [])
                db[key] = _jdump(rows[:1] if prefix == 'ubt_hist_' else rows[-1:])
    return db

def _exam_question_meta(q, index):
    return {'id': 'examq' + str(index), 'subject': q.get('subject'), 'subjectName': q.get('subjectName') or _SUBJECT_NAMES.get(q.get('subject'), 'Пән'), 'points': q.get('points', 1), 'text': 'Сұрақ жүктелуде…', 'options': [], 'loaded': False, 'realBank': bool(q.get('realBank'))}

def _exam_question_request(state, sess, d):
    if not sess:
        return {'ok': False, 'msg': 'Аккаунтыңызға кіріңіз'}
    with state['lock']:
        exam = state.get('exams', {}).get(str(d.get('exam') or ''))
        qid = str(d.get('questionId') or '')
        if not exam or exam.get('uid') != sess['uid'] or exam.get('completed') or (exam.get('expires', 0) < time.time()) or (not re.fullmatch('examq\\d+', qid)):
            return {'ok': False, 'msg': 'Белсенді тест табылмады'}
        if 'premiumAtStart' not in exam:
            issue = _subscription_prepare(state, sess, exam)
            if issue:
                return {'ok': False, 'msg': issue, 'upgradeRequired': True}
        index = int(qid[5:])
        if not 0 <= index < len(exam['questions']):
            return {'ok': False, 'msg': 'Сұрақ табылмады'}
        issue = _subject_guard(state, sess, None, exam['questions'])
        if issue:
            return {'ok': False, 'msg': issue}
        issue = _subscription_charge(state, sess, exam, str(d.get('exam')))
        if issue:
            return {'ok': False, 'msg': issue, 'upgradeRequired': True}
        return {'ok': True, 'question': _public_question(exam['questions'][index], index)}

def _send_personal_test(state, sess, d):
    if not sess or not (sess.get('admin') or sess.get('juniorAdmin')):
        return {'ok': False, 'msg': 'Тест жіберуге рұқсат жоқ'}
    with state['lock']:
        source = next((t for t in _available_send_tests(state) if t.get('id') == d.get('testId') and (sess.get('admin') or (t.get('authorId') == sess['uid'] and (not t.get('assignmentId')) and (not t.get('receivedFromAdmin'))))), None)
        target = next((p for p in _profiles(state).values() if p.get('name', '').casefold() == str(d.get('login') or '').strip().casefold() and p.get('accessApproved') is True), None)
        if not source or not target:
            return {'ok': False, 'msg': 'Өз тестіңізді және тіркелген оқушы логинін таңдаңыз'}
        target_session = {'uid': target['id'], 'admin': target['id'] == 'admin', 'juniorAdmin': target['id'] in _admin_uids(state)}
        issue = _subject_guard(state, target_session, source.get('subject'))
        if issue:
            return {'ok': False, 'msg': 'Оқушы таңдаған пәндерге бұл тест кірмейді'}
        tests = _jload(state['db'].get('ubt_tests', '[]'), list, [])
        tid = 'sent_' + secrets.token_hex(12)
        aid = 'as_' + secrets.token_hex(12)
        clone = {**source, 'id': tid, 'assignmentId': aid, 'isPublic': False, 'status': 'private', 'adminApproved': False, 'reviewFamilySource': source.get('id')}
        clone.pop('classId', None)
        clone.pop('className', None)
        clone.pop('accessCode', None)
        tests.append(clone)
        assignments = _jload(state['db'].get('ubt_assigned_tests', '[]'), list, [])
        assignments.append({'id': aid, 'uid': target['id'], 'testId': tid, 'title': source.get('topic') or 'Тест', 'limit': 1, 'used': 0, 'created': int(time.time()), 'fromUid': sess['uid']})
        _put(state, 'ubt_tests', _jdump(tests))
        _put(state, 'ubt_assigned_tests', _jdump(assignments))
        _commit(state)
        return {'ok': True}

def _start_creative_exam(state, sess):
    with state['lock']:
        banks = _real_bank_cached(state)
        sections = [('history', 20), ('reading', 10)]
        missing = [_SUBJECT_NAMES[k] + ': ' + str(len(banks.get(k, []))) + '/' + str(n) for k, n in sections if len(banks.get(k, [])) < n]
        if missing:
            return {'ok': False, 'msg': 'Шығармашылық бағыт тестіне сұрақ жеткіліксіз: ' + '; '.join(missing)}
        if not _exam_capacity(state, sess['uid']):
            return {'ok': False, 'msg': 'Алдымен белсенді тестті аяқтаңыз'}
        qs = []
        for key, n in sections:
            qs.extend((dict(q, subject=key, subjectName=_SUBJECT_NAMES[key], points=1) for q in _lg_sample(banks[key], n, secrets.SystemRandom())))
        token = secrets.token_urlsafe(32)
        topic = 'Шығармашылық бағыт · 30 сұрақ'
        state['exams'][token] = {'uid': sess['uid'], 'testId': 'real:creative', 'assignmentId': None, 'classId': None, 'owner': False, 'reward': False, 'publishedQuota': False, 'questions': qs, 'topic': topic, 'selfAuthored': False, 'reviewFamily': 'creative', 'expires': time.time() + 70 * 60 + 90}
        issue = _subscription_prepare(state, sess, state['exams'][token])
        if issue:
            state['exams'].pop(token, None)
            return {'ok': False, 'msg': issue, 'upgradeRequired': True}
        _save_exam(state, token)
        return {'ok': True, 'exam': token, 'questions': [_exam_question_meta(q, i) for i, q in enumerate(qs)], 'topic': topic, 'timer': 70 * 60, 'allowInstantFeedback': False}

