            tests = _jload(state['db'].get('ubt_tests', '[]'), list, [])
            source = next((t for t in tests if isinstance(t, dict) and t.get('id') == tid and (sess['admin'] or t.get('authorId') == sess['uid']) and (not t.get('assignmentId'))), None)
            if not cls or not source or (not isinstance(source.get('questions'), list)) or (not source['questions']):
                return {'ok': False, 'msg': 'Сынып немесе өз тестіңіз табылмады'}
            members = list(dict.fromkeys((x for x in cls.get('students', []) if isinstance(x, str) and x != sess['uid'])))
            registered = {p.get('id') for p in _profiles(state).values() if isinstance(p, dict) and p.get('accessApproved') is True}
            members = [x for x in members if x in registered and source.get('subject') in _allowed_subjects(state, {'uid': x, 'admin': False})]
            if not members or len(members) > 100:
                return {'ok': False, 'msg': 'Сыныпта 1–100 тіркелген адам болуы керек'}
            private_id = 'sent_' + secrets.token_hex(12)
            batch = 'batch_' + secrets.token_hex(12)
            clone = dict(source)
            clone.update({'id': private_id, 'authorId': sess['uid'], 'status': 'private', 'isPublic': False, 'adminApproved': False, 'assignmentId': batch})
            clone.pop('classId', None)
            clone.pop('className', None)
            assignments = _jload(state['db'].get('ubt_assigned_tests', '[]'), list, [])
            names = {p.get('id'): key for key, p in _profiles(state).items() if isinstance(p, dict)}
            assignments.extend(({'id': 'as_' + secrets.token_hex(12), 'batchId': batch, 'classId': cid, 'uid': uid, 'login': names.get(uid, ''), 'testId': private_id, 'title': str(source.get('topic') or 'Тест')[:150], 'limit': limit, 'used': 0, 'created': int(time.time())} for uid in members))
            tests.append(clone)
            _put(state, 'ubt_tests', _jdump(tests))
            _put(state, 'ubt_assigned_tests', _jdump(assignments))
            chats = _jload(state['db'].get('ubt_server_access_group_chats', '{}'), dict, {})
